# Validate inputs
for arr in (logp_with_result, logp_call_only, logp_no_call):
    if not isinstance(arr, np.ndarray):
        raise ValueError("Inputs must be numpy arrays")
    if arr.ndim != 2:
        raise ValueError("Inputs must be 2D matrices")
    if arr.size == 0:
        raise ValueError("Inputs must not be empty")
    if np.any(np.isnan(arr)) or np.any(np.isinf(arr)):
        raise ValueError("Inputs must be finite")
    if np.any(arr > 0):
        raise ValueError("Inputs must be nonpositive")
if not (logp_with_result.shape == logp_call_only.shape == logp_no_call.shape):
    raise ValueError("Input matrices must have the same shape")
if isinstance(tau_filter, bool):
    raise ValueError("Boolean values are invalid thresholds")
if not np.isscalar(tau_filter) or not np.isfinite(tau_filter) or tau_filter < 0:
    raise ValueError("tau_filter must be a finite nonnegative scalar")
sum_with = np.sum(logp_with_result, axis=1)
sum_call = np.sum(logp_call_only, axis=1)
sum_none = np.sum(logp_no_call, axis=1)
margin = sum_with - np.maximum(sum_call, sum_none)
keep = margin > tau_filter
return keep, margin
